+    set_cheats_list();
+    for (i = 0; i + 1 < MAX_CHEATLIST && (gCheatList[i] != 0 || gCheatList[i + 1] != 0); i += 2) {
+        /* the same classification as SetupCheats(), to count what it would store */
+        if ((gCheatList[i] & 0xfe000000) == 0x90000000 && nextCodeCanBeHook)
